fn swap_first_and_last(a: &Vec<i32>) -> Vec<i32> {
    let n = a.len();
    debug_assert!(n > 0);

    if n == 1 {
        return a.clone();
    }

    let mut result = a.clone();
    result[0] = a[n - 1];
    result[n - 1] = a[0];
    result
}